#!/usr/bin/env node
'use strict';

// Guard: NO skill SKILL.md may carry an `effort:` frontmatter line, in source
// nor in dist/bm.
//
// Claude Code reads a skill's `effort:` as output_config.effort. Whenever the
// session baseline differs from the pinned value, invoking the skill flips the
// effort and invalidates the prompt cache at both scope boundaries. This
// reverses the earlier deliberate effort:low adoption; the field must stay
// absent everywhere.
//
// This scans every skills/*/SKILL.md frontmatter block (and every
// dist/bm/skills/*/SKILL.md when that directory exists) and fails on any
// `^effort:` line.

const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.join(__dirname, '..');

let failures = 0;
function fail(msg) { console.error(`  FAIL - ${msg}`); failures++; }
function ok(msg) { console.log(`  ok - ${msg}`); }

function frontmatter(content) {
  const m = content.match(/^---\n([\s\S]*?)\n---/);
  return m ? m[1] : '';
}

function skillFiles(skillsDir) {
  if (!fs.existsSync(skillsDir)) return [];
  const out = [];
  for (const entry of fs.readdirSync(skillsDir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const p = path.join(skillsDir, entry.name, 'SKILL.md');
    if (fs.existsSync(p)) out.push(p);
  }
  return out;
}

function scan(label, skillsDir) {
  const files = skillFiles(skillsDir);
  if (files.length === 0) {
    ok(`${label}: no skills directory to scan`);
    return;
  }
  let offenders = 0;
  for (const file of files) {
    const fm = frontmatter(fs.readFileSync(file, 'utf8'));
    if (/^effort:/m.test(fm)) {
      fail(`${path.relative(ROOT, file)}: effort: frontmatter must be removed (prompt-cache invalidation)`);
      offenders++;
    }
  }
  if (offenders === 0) ok(`${label}: no effort: frontmatter (${files.length} skills)`);
}

// Source is always strict.
scan('source skills', path.join(ROOT, 'skills'));

// dist/bm is strict once present (regenerated by node bin/build-bm.cjs).
scan('dist/bm skills', path.join(ROOT, 'dist', 'bm', 'skills'));

if (failures) {
  console.error(`\neffort-frontmatter: ${failures} failure(s)`);
  process.exit(1);
}
console.log('\neffort-frontmatter: all checks passed');
